#!/usr/bin/env Rscript
# run_methylkit_simulator.R
# ---------------------------------------------------------------------------
# methylKit DMC run on a single intrinsic-truth simulator seed.
#
# Reads the 6 per-sample .cov.gz files generated by Task 5 Step 1
# (uv run python ... AMP -> bismark .cov conversion), runs methylKit's
# calculateDiffMeth in a 3v3 case/control design, and writes a per-CpG
# TSV to --out.
#
# The intent is to produce a parquet/tsv that the Phase 4 eval
# (eval_simulator_intrinsic.py) can score against truth.parquet for
# the "intrinsic-truth gap" parallel-column claim (spec §2.1).
#
# Usage:
#   Rscript run_methylkit_simulator.R \
#       --in-dir  benchmark/data/study1b_simulator/seed=2026000/bismark_cov \
#       --out     benchmark/data/study1b_simulator/seed=2026000/methylkit.tsv \
#       [--cores 1]
#
# Outputs:
#   <out>                   - per-CpG TSV with chr, start, end, pvalue, qvalue, meth.diff
#   <out>.sessioninfo.txt  - R sessionInfo() for reproducibility
#   <out>.timing.tsv       - wall + CPU time for read/unite/diffmeth phases
# ---------------------------------------------------------------------------

suppressPackageStartupMessages({
  library(optparse)
  library(methylKit)
})

opt_list <- list(
  make_option("--in-dir",  type = "character", help = "Directory containing the 6 .cov.gz files"),
  make_option("--out",     type = "character", help = "Output TSV path for per-CpG results"),
  make_option("--cores",   type = "integer",   default = 1L,
              help = "mc.cores for calculateDiffMeth (Windows: keep 1)")
)
opt <- parse_args(OptionParser(option_list = opt_list))
if (is.null(opt$`in-dir`) || is.null(opt$out)) {
  stop("--in-dir and --out are required")
}

in_dir <- opt$`in-dir`
out_path <- opt$out
out_dir <- dirname(out_path)
dir.create(out_dir, recursive = TRUE, showWarnings = FALSE)

# ---- Discover input files in deterministic order --------------------------
# Expect 6 files named amp.coverage=10.sample{1..6}.cov.gz.
# Samples 1-3 are treatment (treat_*), 4-6 are control (ctrl_*).
files_all <- sort(list.files(in_dir, pattern = "\\.cov\\.gz$", full.names = TRUE))
if (length(files_all) != 6L) {
  stop(sprintf("expected 6 .cov.gz files in %s, found %d", in_dir, length(files_all)))
}
cat("input files (sorted):\n")
for (f in files_all) cat("  ", basename(f), "\n")

sample_ids <- list("treat_1", "treat_2", "treat_3", "ctrl_1", "ctrl_2", "ctrl_3")
# methylKit convention: 1 = treatment, 0 = control.
treatment <- c(1L, 1L, 1L, 0L, 0L, 0L)

# ---- Phase 1: read + unite -----------------------------------------------
t_read_0 <- proc.time()
obj <- methRead(
  as.list(files_all),
  sample.id = sample_ids,
  treatment = treatment,
  assembly  = "sim",
  pipeline  = "bismarkCoverage",
  context   = "CpG",
  mincov    = 1L
)
cat(sprintf("methRead: %d samples loaded\n", length(obj)))
t_read <- proc.time() - t_read_0

t_unite_0 <- proc.time()
# destrand=FALSE because the simulator AMP files don't carry strand info;
# every CpG is treated as a single record at its base position.
united <- methylKit::unite(obj, destrand = FALSE)
cat(sprintf("unite: %d sites covered in all samples\n", nrow(united)))
t_unite <- proc.time() - t_unite_0

# ---- Phase 2: calculateDiffMeth -------------------------------------------
t_diff_0 <- proc.time()
diff <- calculateDiffMeth(united, mc.cores = opt$cores)
t_diff <- proc.time() - t_diff_0
cat(sprintf("calculateDiffMeth: %d sites tested\n", nrow(diff)))

# ---- Write per-CpG output ------------------------------------------------
out_df <- getData(diff)
# Standardise column names so eval_simulator_intrinsic.py can ingest
# uniformly across tools. methylKit's getData() returns:
#   chr, start, end, strand, pvalue, qvalue, meth.diff
write.table(
  out_df, file = out_path, sep = "\t",
  quote = FALSE, row.names = FALSE
)
cat(sprintf("wrote %s (%d rows)\n", out_path, nrow(out_df)))

# ---- Timings sidecar ------------------------------------------------------
timing_df <- data.frame(
  phase    = c("read",        "unite",       "diffmeth"),
  wall_s   = c(t_read["elapsed"], t_unite["elapsed"], t_diff["elapsed"]),
  cpu_s    = c(t_read["user.self"] + t_read["sys.self"],
               t_unite["user.self"] + t_unite["sys.self"],
               t_diff["user.self"] + t_diff["sys.self"])
)
timing_path <- paste0(out_path, ".timing.tsv")
write.table(timing_df, file = timing_path, sep = "\t", quote = FALSE, row.names = FALSE)
cat(sprintf("wrote %s\n", timing_path))

# ---- sessionInfo for reproducibility -------------------------------------
sinfo_path <- paste0(out_path, ".sessioninfo.txt")
sink(sinfo_path)
cat("# run_methylkit_simulator.R session info\n\n")
cat(sprintf("# in_dir : %s\n", in_dir))
cat(sprintf("# out    : %s\n\n", out_path))
print(sessionInfo())
sink()
cat(sprintf("wrote %s\n", sinfo_path))

cat("\nDONE\n")
